    ('schema', '\n        CREATE TABLE IF NOT EXISTS brigade_payments (\n            id SERIAL PRIMARY KEY,\n            company_id INT,\n            contract_id INT,\n            project_payment_id INT,\n            amount NUMERIC(14,2) DEFAULT 0,\n            paid_by VARCHAR(255),\n            paid_date DATE,\n            note TEXT,\n            created_at TIMESTAMP DEFAULT NOW()\n        );'),
